/**
 * Brand cover — page 1 of every generated datasheet.
 *
 * Pre-rendered from the reference `cover-new-collection_fixed.pptx` via
 * LibreOffice and embedded as a base64 data URI rather than a binary file.
 *
 * WHY BASE64-IN-TS: the single-product download path runs in a Vercel
 * serverless function, which has no LibreOffice to render the cover at
 * request time, and a loose binary asset is not guaranteed to be traced into
 * the deployment bundle. A string in a module is the one form that resolves
 * identically in Next.js (admin) and plain tsx (the worker), with zero
 * bundler configuration in either.
 *
 * 1240x1754px (150 DPI at A4), JPEG q74, ~400KB (~533KB as base64 — this is
 * added to EVERY generated file, so raising the resolution has a real cost
 * across a full-catalog bulk export).
 *
 * DO NOT hand-edit. To regenerate after a cover redesign:
 *   docker run --rm -v "$PWD":/w -w /w datasheet-worker-bulk \\
 *     soffice --headless -env:UserInstallation=file:///tmp/lo-cover \\
 *     --convert-to png --outdir /w /w/cover.pptx
 *   sips -Z 1754 -s format jpeg -s formatOptions 74 cover.png --out cover.jpg
 * then base64-encode cover.jpg into the constant below.
 */
export const COVER_IMAGE_DATA_URI = "data:image/jpeg;base64,";
